async function joinBookWaitlist() {
  const email = await dialog.prompt({
    title: "Join the preorder list",
    body: "The Anchor ships from Lagos later this year. Leave your email and you'll be first to know when preorders open \u2014 print and digital.",
    label: "Email",
    placeholder: "you@email.com",
    inputType: "email",
    cta: "Join the list"
  });
  if (!email) return;
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    toast.error("That email doesn't look right.", "Preorder list");
    return;
  }
  try {
    await NGGApi.public.newsletter(email, "book-waitlist");
    toast.success("You're on the list. We'll email you when preorders open.", "The Anchor");
  } catch (e) {
    const code = e.code || e.message;
    toast.error(code === "rate_limited" ? "Too many tries \u2014 wait a few minutes." : "Couldn't save your email. Try again.", "Preorder list");
  }
}
