function useAdminDrawer(onClose, guard = true) {
  const panelRef = React.useRef(null);
  const touched = React.useRef(false);
  const close = React.useCallback(() => {
    if (guard && touched.current && typeof dialog !== "undefined" && dialog.confirm) {
      dialog.confirm({ title: "Discard changes?", body: "You have edits that haven't been saved yet.", cta: "Discard", cancel: "Keep editing", danger: true }).then((ok) => {
        if (ok) onClose();
      });
    } else {
      onClose();
    }
  }, [onClose, guard]);
  React.useEffect(() => {
    const prev = document.activeElement;
    const el = panelRef.current;
    if (el) {
      const f = el.querySelector("input,select,textarea,button:not(.admin-drawer-close)");
      if (f) setTimeout(() => {
        try {
          f.focus();
        } catch (_) {
        }
      }, 40);
    }
    const onKey = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        close();
        return;
      }
      if (e.key === "Tab" && el) {
        const f = el.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])');
        if (!f.length) return;
        const a = f[0], b = f[f.length - 1];
        if (e.shiftKey && document.activeElement === a) {
          e.preventDefault();
          b.focus();
        } else if (!e.shiftKey && document.activeElement === b) {
          e.preventDefault();
          a.focus();
        }
      }
    };
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      if (prev && prev.focus) {
        try {
          prev.focus();
        } catch (_) {
        }
      }
    };
  }, [close]);
  return { panelRef, close, onInput: () => {
    touched.current = true;
  } };
}
